<script setup lang="ts">import {ref,onMounted} from 'vue';import {request} from '../api/client';import type {Audit} from '../types/domain';import {useTask} from '../hooks/useTask';import {date} from '../utils/format';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';const rows=ref<Audit[]>([]),{error,perform}=useTask();async function load(){rows.value=await request<Audit[]>('/audit');}onMounted(()=>perform(load));</script><template><PageHeading eyebrow="TRACE / RESEARCH ACCOUNTABILITY" title="每个动作，都留下一行依据" description="记录最近 100 次写入与交付请求。拒绝的操作也会保留状态码。"><button class="outline" @click="perform(load)">刷新记录 ↻</button></PageHeading><ErrorNotice :message="error" @retry="perform(load)"/><div class="table-wrap"><table><thead><tr><th>时间</th><th>操作人</th><th>动作</th><th>HTTP 状态</th></tr></thead><tbody><tr v-for="a in rows" :key="a.id"><td>{{date(a.created_at)}}</td><td>{{a.actor}}</td><td><code>{{a.action}}</code></td><td><span :class="a.status_code<400?'success':'warning'">{{a.status_code}}</span></td></tr></tbody></table></div><p class="source-note">健康检查与一般读取不写入审计，避免掩盖研究操作。</p></template>
